mapper.select:
SELECT *
FROM pull_task_material_member
WHERE group_execution_id = #{groupExecutionId}
  AND pull_status = #{pullStatus}
  AND pull_call_id IS NULL
  AND active_pull_attempt_id IS NULL
  AND pull_failure_count < #{maxFailureCount}
ORDER BY member_seq ASC
LIMIT #{limit}

mapper.update:
UPDATE pull_task_material_member
SET pull_call_id = #{pullCallId},
    pull_status = #{targetStatus},
    updated_at = #{now}
WHERE pull_call_id IS NULL
  AND pull_status = #{expectedStatus}
  AND id IN
  #{id}

UPDATE pull_task_material_member
SET pull_call_id = #{binding.pullCallId},
    active_pull_attempt_id = #{binding.attemptId},
    pull_reason_code = NULL,
    pull_reason_message = NULL,
    pull_result_at = NULL,
    updated_at = #{binding.now}
WHERE id = #{binding.participantId}
  AND pull_status = #{guard.expectedStatus}
  AND pull_call_id IS NULL
  AND active_pull_attempt_id IS NULL
  AND pull_failure_count < #{guard.maxFailureCount}

UPDATE pull_task_material_member
SET pull_status = #{targetStatus},
    last_puller_group_account_id = #{binding.pullerGroupAccountId},
    updated_at = #{binding.now}
WHERE id = #{binding.participantId}
  AND pull_status = #{expectedStatus}
  AND active_pull_attempt_id = #{binding.attemptId}
  AND pull_call_id = #{binding.pullCallId}

UPDATE pull_task_material_member
SET pull_status = #{transition.target.status},
    pull_failure_count = #{transition.target.failureCount},
    pull_call_id = #{transition.target.pullCallId},
    active_pull_attempt_id = #{transition.target.activeAttemptId},
    pull_reason_code = #{transition.result.reasonCode},
    pull_reason_message = #{transition.result.reasonMessage},
    wa_jid = COALESCE(#{transition.result.resultJid}, wa_jid),
    pull_result_at = #{transition.result.occurredAt},
    updated_at = #{transition.scope.now}
WHERE id = #{transition.scope.participantId}
  AND active_pull_attempt_id = #{transition.scope.attemptId}
  AND pull_failure_count = #{transition.expected.failureCount}
  AND pull_status IN
  #{status}

UPDATE pull_task_material_member
SET pull_status = #{transition.target.status},
    pull_call_id = #{transition.target.pullCallId},
    active_pull_attempt_id = CASE
      WHEN active_pull_attempt_id = #{transition.scope.attemptId}
        THEN #{transition.target.activeAttemptId}
      ELSE active_pull_attempt_id
    END,
    pull_reason_code = NULL,
    pull_reason_message = NULL,
    wa_jid = COALESCE(#{transition.result.resultJid}, wa_jid),
    pull_result_at = #{transition.result.occurredAt},
    updated_at = #{transition.scope.now}
WHERE id = #{transition.scope.participantId}
  AND pull_status <> #{transition.target.status}

UPDATE pull_task_material_member
SET pull_status = #{transition.targetStatus},
    pull_reason_code = #{transition.result.reasonCode},
    pull_reason_message = #{transition.result.reasonMessage},
    wa_jid = COALESCE(#{transition.result.resultJid}, wa_jid),
    pull_result_at = #{transition.now},
    updated_at = #{transition.now}
WHERE id = #{transition.id}
  AND pull_status IN
  #{status}

