  AND pull_status IN
  #{status}

SELECT *
FROM pull_task_material_member
WHERE group_execution_id = #{groupExecutionId}
  AND admin_required = #{adminRequired}
  AND pull_status = #{pullStatus}
  AND admin_status = #{adminStatus}
ORDER BY member_seq ASC

mapper.update:
UPDATE pull_task_material_member
SET admin_status = #{submittedAdminStatus},
    admin_command_id = #{adminCommandId},
    updated_at = #{now}
WHERE id = #{id}
  AND admin_status = #{expectedAdminStatus}

UPDATE pull_task_material_member
SET admin_status = #{adminStatus},
    admin_reason_code = #{reasonCode},
    admin_result_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND admin_status = #{expectedAdminStatus}

UPDATE pull_task_material_member
SET admin_status = #{transition.targetStatus},
    admin_reason_code = #{transition.result.reasonCode},
    admin_result_at = #{transition.now},
    updated_at = #{transition.now}
WHERE id = #{transition.id}
  AND admin_status IN
  #{status}

UPDATE pull_task_material_member
SET admin_status = #{pendingAdminStatus},
    admin_command_id = NULL,
    admin_reason_code = #{reasonCode},
    admin_result_at = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND admin_status = #{expectedAdminStatus}

UPDATE pull_task_material_member
SET pull_status = #{targetStatus},
    pull_result_at = #{now},
    updated_at = #{now}
WHERE pull_status = #{expectedStatus}
  AND pull_call_id IS NULL
  AND EXISTS (
    SELECT 1
    FROM pull_task_group_execution execution_row
    WHERE execution_row.id = pull_task_material_member.group_execution_id
      AND execution_row.task_id = #{taskId}
  )

UPDATE pull_task_material_member
SET pull_status = #{targetPullStatus},
    pull_call_id = NULL,
    active_pull_attempt_id = NULL,
    pull_result_at = #{now},
    updated_at = #{now}
WHERE pull_status = #{expectedPullStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_pull_call planned_call
    WHERE planned_call.id = pull_task_material_member.pull_call_id
      AND planned_call.task_id = #{taskId}
      AND planned_call.call_status = #{plannedCallStatus}
  )

UPDATE pull_task_material_member
SET admin_status = #{targetStatus},
    admin_result_at = #{now},
    updated_at = #{now}
WHERE admin_status = #{expectedStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_group_execution execution_row
    WHERE execution_row.id = pull_task_material_member.group_execution_id
      AND execution_row.task_id = #{taskId}
  )

UPDATE pull_task_material_member
SET pull_status = #{targetStatus},
    pull_result_at = #{now},
    updated_at = #{now}
WHERE group_execution_id = #{groupExecutionId}
  AND pull_status = #{expectedStatus}
  AND pull_call_id IS NULL

UPDATE pull_task_material_member
SET pull_status = #{targetPullStatus},
    pull_call_id = NULL,
    active_pull_attempt_id = NULL,
    pull_result_at = #{now},
    updated_at = #{now}
WHERE group_execution_id = #{groupExecutionId}
  AND pull_status = #{expectedPullStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_pull_call planned_call
    WHERE planned_call.id = pull_task_material_member.pull_call_id
      AND planned_call.group_execution_id = #{groupExecutionId}
      AND planned_call.call_status = #{plannedCallStatus}
  )

UPDATE pull_task_material_member
SET admin_status = #{targetStatus},
    admin_result_at = #{now},
    updated_at = #{now}
WHERE group_execution_id = #{groupExecutionId}
  AND admin_status = #{expectedStatus}

UPDATE pull_task_material_member
SET pull_status = #{targetStatus},
    pull_call_id = CASE WHEN #{releaseBinding} THEN NULL ELSE pull_call_id END,
    active_pull_attempt_id = CASE
      WHEN #{releaseBinding} THEN NULL ELSE active_pull_attempt_id END,
    pull_result_at = #{now},
    updated_at = #{now}
WHERE pull_status = #{expectedStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_pull_call call_row
    JOIN protocol_command_outbox outbox_row
      ON outbox_row.command_id = call_row.command_id
    WHERE call_row.id = pull_task_material_member.pull_call_id
      AND call_row.task_id = #{taskId}

        AND call_row.group_execution_id = #{groupExecutionId}

      AND outbox_row.status = #{canceledOutboxStatus}
      AND outbox_row.deleted_at IS NULL
  )

UPDATE pull_task_material_member
SET admin_status = #{targetStatus},
    admin_result_at = #{now},
    updated_at = #{now}
WHERE admin_status = #{expectedStatus}
  AND EXISTS (
    SELECT 1
    FROM pull_task_group_execution execution_row
    JOIN protocol_command_outbox outbox_row
      ON outbox_row.command_id = pull_task_material_member.admin_command_id
    WHERE execution_row.id = pull_task_material_member.group_execution_id
      AND execution_row.task_id = #{taskId}

        AND execution_row.id = #{groupExecutionId}

      AND outbox_row.status = #{canceledOutboxStatus}
      AND outbox_row.deleted_at IS NULL
  )
